export const BOOSTER_TYPES=["surge","stream","drag"];export function boosterDifficulty(t,a,r){const e=Math.max(1,Number(r)||1),n=Math.max(1,Number(a)||1);return Math.max(0,Math.min(1,(Number(t)||0)/n/e))}export function boosterSpawnInterval(t,a,r){const e=boosterDifficulty(a,r,t.progressionScreens);return t.startIntervalMs+(t.minIntervalMs-t.startIntervalMs)*e}export function boosterWeights(t,a,r,e){const n=boosterDifficulty(r,e,t.progressionScreens),m=Math.max(1e-6,Number(t.pressureThreshold)||.6),u=Math.max(-1,Math.min(1,(Number(a)||0)/m));return{surge:Math.max(.01,t.surge.spawnWeight*(1-Math.abs(u)*.55)),stream:Math.max(.01,t.stream.spawnWeight*(1+Math.max(0,u)*1.4)),drag:Math.max(.01,t.drag.spawnWeight*(1+Math.max(0,-u)*2+n*t.drag.heightWeightBonus))}}export function pickBoosterType(t,a=Math.random()){const r=BOOSTER_TYPES.reduce((n,m)=>n+Math.max(0,Number(t[m])||0),0);if(!r)return"surge";let e=Math.max(0,Math.min(.999999999,a))*r;for(const n of BOOSTER_TYPES)if(e-=Math.max(0,Number(t[n])||0),e<=0)return n;return BOOSTER_TYPES.at(-1)}export function boosterCorridor(t,a,r,e,n,m,u){const h=Math.max(0,Number(a)||0)/Math.max(1,Number(e)||1),o=Math.max(0,Number(r)||0)*h*Math.max(0,Number(n)||0),s=Math.max(m,t-o),c=Math.min(u,t+o);if(c>=s)return[s,c];const i=Math.max(m,Math.min(u,t));return[i,i]}export function streamAscentVelocity(t,a,r,{entered:e=!1}={}){const n=Math.max(0,Number(a.entryImpulse)||0),m=Math.max(0,Number(a.minAscentSpeed)||0),u=Math.max(0,Number(a.accel)||0),h=e?Math.max(Number(t)||0,n):Number(t)||0;return Math.max(m,h+u*Math.max(0,Number(r)||0))}
